import {catalog,isOwned,activeFrame} from '../systems/profile.js';
import {JOBS,HOUSING,CONFIG,xpNeeded} from '../data/config.js';
import {income} from '../core/game.js';
import {t,money,number} from '../locales/index.js';
import {icon} from './icons.js';
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const nickname=s=>s.profile.nickname||t('profile.defaultName');
export const avatar=(s,frame=activeFrame(s),big=false)=>`<span class="profile-avatar frame-${frame} ${big?'large':''}" aria-hidden="true"><span>Z</span></span>`;
const name=(kind,id)=>t(`${kind==='frame'?'frame':'title'}.${id}`);
const btn=(label,action,id,disabled=false,extra='')=>`<button class="button secondary" data-action="${action}" data-id="${id}" ${disabled?'disabled':''} ${extra}>${label}</button>`;
export function profileScreen(s,view='frames'){
 const kind=view==='titles'?'title':'frame',current=kind==='frame'?activeFrame(s):s.profile.title;
 return `<section class="profile-hero">${avatar(s,activeFrame(s),true)}<h3>${escape(nickname(s))}</h3><span class="profile-title title-${s.profile.title}">${name('title',s.profile.title)}</span><small>${name('frame',activeFrame(s))}</small><div class="profile-level"><strong>${t('ui.level')} ${s.level}</strong><span>${s.level===CONFIG.maxLevel?t('ui.max'):`${number(s.xp)} / ${number(xpNeeded(s.level))} XP`}</span></div><div class="progress"><span style="width:${s.level===CONFIG.maxLevel?100:Math.min(100,s.xp/xpNeeded(s.level)*100)}%"></span></div></section>
 <div class="profile-facts"><div>${icon('work')}<span>${t(JOBS.find(j=>j.id===s.job).name)}</span></div><div>${icon('life')}<span>${t(HOUSING[s.housing].name)}</span></div><div>${icon('coin')}<strong>${money(income(s))} / ${t('ui.sec')}</strong></div></div>
 <details class="profile-name"><summary>${t('profile.nickname')}</summary><label for="profile-name">${t('profile.nickname')}</label><div><input id="profile-name" maxlength="40" value="${escape(s.profile.nickname)}" placeholder="${escape(t('profile.defaultName'))}" autocomplete="off">${btn(t('profile.save'),'profileName','')}</div><small>${t('profile.nameLimit')}</small></details>
 <div class="profile-shop-heading"><strong>${t('profile.personalize')}</strong><span>${icon('gem')}${number(s.gems)}</span></div><div class="segmented profile-tabs">${btn(t('profile.frames'),'profileTab','frames',false,view==='frames'?'aria-pressed="true"':'aria-pressed="false"')}${btn(t('profile.titles'),'profileTab','titles',false,view==='titles'?'aria-pressed="true"':'aria-pressed="false"')}</div><p class="profile-note">${t('profile.cosmeticOnly')}</p>
 <p id="profile-feedback" role="status"></p><div class="cosmetic-grid ${kind==='title'?'titles-grid':''}">${catalog(s,kind).map(item=>{const owned=isOwned(s,kind,item),used=current===item.id;return `<article class="cosmetic-card ${used?'equipped':''} ${!owned&&!item.price?'locked':''}"><button class="cosmetic-preview" data-action="profilePreview" data-id="${kind}:${item.id}" aria-label="${escape(t('ui.preview')+': '+name(kind,item.id))}">${kind==='frame'?avatar(s,item.id):`<span class="profile-title title-${item.id}">${name(kind,item.id)}</span>`}</button><h3>${name(kind,item.id)}</h3><p>${item.price?`${item.price} ${icon('gem')}`:t('profile.rule.'+item.rule)}</p>${btn(t(used?'ui.equipped':owned?'ui.choose':item.price?'ui.buy':'ui.preview'),used?'profileSelect':owned?'profileSelect':'profilePreview',`${kind}:${item.id}`,used)}</article>`;}).join('')}</div>`;
}
export function cosmeticPreview(s,kind,id){const item=catalog(s,kind).find(x=>x.id===id);if(!item)return '';const owned=isOwned(s,kind,item),used=(kind==='frame'?activeFrame(s):s.profile.title)===id;return `<div class="profile-hero cosmetic-detail">${avatar(s,kind==='frame'?id:activeFrame(s),true)}<h3>${escape(nickname(s))}</h3><span class="profile-title title-${kind==='title'?id:s.profile.title}">${name('title',kind==='title'?id:s.profile.title)}</span><h2>${name(kind,id)}</h2><p>${t('profile.cosmeticOnly')}</p><strong class="cosmetic-price">${item.price?`${item.price} ${icon('gem')}`:t('profile.rule.'+item.rule)}</strong><small>${t('profile.balance')}: ${number(s.gems)} ${icon('gem')}</small>${btn(t(used?'ui.equipped':owned?'ui.choose':item.price?'ui.buy':'profile.locked'),owned?'profileSelect':'profileBuy',`${kind}:${id}`,used||(!owned&&!item.price))}${btn(t('profile.back'),'profile','')}<p id="profile-feedback" role="status"></p></div>`;}
